        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        internal static FixedUtf8String GetName(ViewKind kind) => _structNames[(int) kind - 1];

        internal static string GetFieldName(ViewKind kind)
        {
            return kind switch
            {
                ViewKind.AddressMap       => "Address Map",
                ViewKind.ThunkMap         => "Thunk Map",
                ViewKind.SectionMap       => "Section Map",
                ViewKind.DNRBSecOffset    => "secOffset",
                ViewKind.DNRBVersion      => "version",
                ViewKind.DNRBSignature    => "signature",
                ViewKind.DNRBSecTblOffset => "secTblOffset",
                ViewKind.LfoDir           => "lfoDir",
                ViewKind.cDir             => "cDir",
                ViewKind.LfoBase          => "lfoBase"
            };
        }
